    if (variante === 'fille') { for (const u of [-1, 1]) a.ovale(0.06 * k, PIERRE_F, { ...o(u * 0.17, yT + 0.03, 0.04), sx: 0.8, sy: 1.5, sz: 0.8 }, 8); a.ovale(0.16 * k, PIERRE_F, { ...o(0, yT + 0.05, 0.07), sx: 1.0, sy: 0.75, sz: 0.95 }, 10); }
    else { a.ovale(0.16 * k, PIERRE_F, { ...o(0, yT + 0.05, 0.07), sx: 1.0, sy: 0.75, sz: 0.95 }, 10); for (let i = -2; i <= 2; i++) a.cone(0.03 * k, 0.08 * k, 4, PIERRE_F, { ...o(i * 0.04, yT + 0.11, 0.19), rx: 2.2 }); }
