      for (const [pu, py] of [[G.nef, G.plafond], [G.nef, G.frise], [G.porche, G.plafond], [G.porche, HAUT_PORCHE], [ub, FEN.yb]]) for (const s of [-1, 1]) l.push((Math.atan2(s * pu, py - FEN.cy) + 2 * PI) % (2 * PI));
