    for (const s of [-1, 1]) quad(coque, P3(s * G.porte, 0.1, G.v0), P3(s * G.demi, 0.1, G.v0), P3(s * G.demi, G.plafond, G.v0), P3(s * G.porte, G.plafond, G.v0), PAROI, [0, 0, 1]);
