        await jeu.attendre(500);
        await jeu.dire(jeu.txn('osato1'));
        jeu.cacherVoyageur(false);
        jeu.cadrer({ de: [OSATO.x - 5, HAUT.y + 2.4, OSATO.z + 3.2], vers: [OSATO.x + 30, HAUT.y - 14, OSATO.z - 22], champ: 55 });
        await jeu.attendre(700);
